    .form-status {
      margin-top: 1rem;
      padding: 0.9rem 1rem;
      border-radius: 14px;
      background: rgba(6, 118, 71, 0.08);
      color: var(--success);
      border: 1px solid rgba(6, 118, 71, 0.18);
    }

    @media (max-width: 640px) {
      main {
        padding-inline: 0.75rem;
      }

      .hero,
      form {
        padding-left: 1.25rem;
        padding-right: 1.25rem;
      }

