 <body>
   <a class="skip-link" href="#support-form">Skip to contact form</a>

   <main id="main-content">
     <section class="support-shell" aria-labelledby="support-title">
       <header class="hero">
         <p class="eyebrow">Support</p>
         <h1 id="support-title">Contact our support team</h1>
         <p>Send us your details and we’ll get back to you as soon as possible.</p>
       </header>

       <form id="support-form" novalidate>
         <p class="form-note">Fields marked with <span aria-hidden="true">*</span> are required.</p>

         <div class="form-field">
           <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
           <input id="full-name" name="fullName" type="text" autocomplete="name" required aria-describedby="full-name-error">
           <p class="field-error" id="full-name-error" hidden>Error: Enter your full name.</p>
         </div>

         <div class="form-field">
           <label for="email-address">Email address <span class="required-mark" aria-hidden="true">*</span></label>
           <input id="email-address" name="emailAddress" type="email" autocomplete="email" required inputmode="email" aria-describedby="email-address-error">
           <p class="field-error" id="email-address-error" hidden>Error: Enter a valid email address.</p>
         </div>

         <div class="form-field">
           <label for="phone-number">Phone number</label>
           <input
             id="phone-number"
             name="phoneNumber"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             aria-describedby="phone-number-hint"
             placeholder="+1 555 123 4567"
           >
           <p class="field-hint" id="phone-number-hint">Optional. Use international format like +1 555 123 4567.</p>
         </div>

         <div class="actions">
           <button type="submit">Send message</button>
         </div>

         <p id="form-status" class="form-status" role="status" aria-live="polite" hidden>Thanks — your message has been prepared for sending.</p>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const status = document.getElementById('form-status');
     const fields = [
       {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         validate: (input) => input.value.trim().length > 0,
       },
       {
         input: document.getElementById('email-address'),
         error: document.getElementById('email-address-error'),
         validate: (input) => input.checkValidity(),
       },
     ];

     const setFieldState = ({ input, error }, isValid) => {
       if (isValid) {
         input.removeAttribute('aria-invalid');
       } else {
         input.setAttribute('aria-invalid', 'true');
       }
       error.hidden = isValid;
     };

     const validateField = (field) => {
       const isValid = field.validate(field.input);
       setFieldState(field, isValid);
       return isValid;
     };

     const validateForm = () => {
       const firstInvalid = fields.find((field) => !validateField(field));
       return firstInvalid ?? null;
     };

     fields.forEach((field) => {
       field.input.addEventListener('input', () => {
         if (field.input.getAttribute('aria-invalid') === 'true') {
           validateField(field);
         }
       });

       field.input.addEventListener('blur', () => {
         validateField(field);
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       status.hidden = true;

       const firstInvalid = validateForm();
       if (firstInvalid) {
         firstInvalid.input.focus();
         return;
       }

       status.hidden = false;
       form.reset();
       fields.forEach((field) => {
         field.input.removeAttribute('aria-invalid');
         field.error.hidden = true;
       });
       document.getElementById('full-name').focus();
     });
   </script>
 </body>
